361	        // 幂等记录与业务数据均持久化在数据库中，重启后语义仍成立
362	        assertThat(count("SELECT COUNT(*) FROM idempotency_request")).isEqualTo(3);
363	        assertThat(count("SELECT COUNT(*) FROM consent_grant WHERE status = 'REVOKED'")).isEqualTo(1);
364	        // 已撤回数据物理保留但不可见，重启后也不会重新可见
