372	    void concurrentWritesSameRecordKeySamePayloadProduceSingleRecord() throws Exception {
373	        grant("g-1", "subj-a", "RESEARCH").andExpect(status().isOk());
374	        int threads = 8;
375	        ExecutorService pool = Executors.newFixedThreadPool(threads);
376	        CountDownLatch ready = new CountDownLatch(threads);
377	        CountDownLatch start = new CountDownLatch(1);
378	        List<Callable<String>> tasks = new ArrayList<>();
379	        for (int i = 0; i < threads; i++) {
380	            String requestId = "w-concurrent-" + i;
381	            tasks.add(() -> {
382	                ready.countDown();
383	                start.await();
384	                return consentService.write(new RecordWriteRequest(
385	                        requestId, "subj-a", Purpose.RESEARCH, "rec-1", "same-payload")).payload();
386	            });
387	        }
388	        List<Future<String>> futures = new ArrayList<>();
389	        for (Callable<String> task : tasks) {
390	            futures.add(pool.submit(task));
391	        }
392	        assertThat(ready.await(10, TimeUnit.SECONDS)).isTrue();
393	        start.countDown();
394	        for (Future<String> future : futures) {
395	            assertThat(future.get(20, TimeUnit.SECONDS)).isEqualTo("same-payload");
396	        }
397	        pool.shutdown();
398	        assertThat(count("SELECT COUNT(*) FROM consent_record")).isEqualTo(1);
399	        assertThat(count("SELECT COUNT(*) FROM idempotency_request WHERE operation = 'WRITE'")).isEqualTo(threads);
400	    }
